// Get all inputs
const inputs = $input.all();

// Find Set Variables and extract topic
let topic = 'Content Batch';
for (const input of inputs) {
  if (input.json.topic) {
    topic = input.json.topic;
    break;
  }
}

// Extract content from each OpenAI node by checking for its unique output
// We'll build a map of all content first
const allContent = [];
for (const input of inputs) {
  if (input.json.output && input.json.output[0]?.content?.[0]?.text) {
    allContent.push(input.json.output[0].content[0].text);
  }
}

// Now detect each piece by its unique markers
let blog = 'Blog not generated';
let linkedin1 = 'LinkedIn 1 not generated';
let linkedin2 = 'LinkedIn 2 not generated';
let facebook = 'Facebook not generated';
let x1 = 'X post 1 not generated';
let x2 = 'X post 2 not generated';
let newsletter = 'Newsletter not generated';

for (const content of allContent) {
  // Blog: has TITLE: and META DESCRIPTION
  if (content.includes('TITLE:') && content.includes('META DESCRIPTION')) {
    blog = content;
  }
  // LinkedIn Educational: has "LINKEDIN POST (Educational)"
  else if (content.includes('LINKEDIN POST (Educational)')) {
    linkedin1 = content;
  }
  // LinkedIn Engagement: has "LINKEDIN POST (Engagement)" or "X POST (Engagement)" with long form
  else if (content.includes('LINKEDIN POST (Engagement)')) {
    linkedin2 = content;
  }
  // Facebook: has ❌ and ✔ and DM/Comment with short length
    else if (content.includes('❌') && content.includes('✔') && content.includes('Comment ') && content.length < 800) {
    facebook = content;
  }
  // X Insight: has "X POST (Insight)"
  else if (content.includes('X POST (Insight)')) {
    x1 = content;
  }
  // X Engagement: has "X POST (Engagement)" and is very short
    else if (content.includes('X POST (Engagement)')) {
  x2 = content;
  }
  // Newsletter: has "NEWSLETTER SECTION:" and "SECTION TITLE:" and "Quick Tips"
  else if (content.includes('NEWSLETTER SECTION:') && content.includes('SECTION TITLE:') && content.includes('Quick Tips')) {
    newsletter = content;
  }
}

// Format into organized document
const formattedContent = `CONTENT BATCH - ${topic}
Generated: ${new Date().toLocaleDateString()}

═══════════════════════════════════════════════════════

📝 BLOG POST

${blog}

═══════════════════════════════════════════════════════

💼 LINKEDIN POSTS

Post 1 (Educational):
${linkedin1}

---

Post 2 (Engagement):
${linkedin2}

═══════════════════════════════════════════════════════

📘 FACEBOOK POST

${facebook}

═══════════════════════════════════════════════════════

🐦 X POSTS

Post 1 (Insight):
${x1}

---

Post 2 (Engagement):
${x2}

═══════════════════════════════════════════════════════

📧 NEWSLETTER SECTION

${newsletter}

═══════════════════════════════════════════════════════

END OF CONTENT BATCH
`;

return [{ json: { content: formattedContent, topic: topic } }];

